import LoginPage from '../support/pages/LoginPage';
import NavigationComponent from '../support/pages/NavigationComponent';

// Helper: logs violations to Cypress test log and throws if critical/serious ones exist
const handleA11yViolations = (violations) => {
  const blocking = violations.filter(v =>
    v.impact === 'critical' || v.impact === 'serious'
  );

  violations.forEach((v) => {
    cy.log(`[a11y] ${v.impact?.toUpperCase()}: ${v.description}`);
    cy.log(`  Rule: ${v.id} | WCAG: ${v.tags.filter(t => t.startsWith('wcag')).join(', ')}`);
    cy.log(`  Help: ${v.helpUrl}`);
    v.nodes.slice(0, 2).forEach(node => {
      cy.log(`  Element: ${node.html.slice(0, 100)}`);
    });
  });

  if (blocking.length > 0) {
    throw new Error(
      `${blocking.length} critical/serious WCAG 2.1 AA violation(s) found. ` +
      `See Cypress logs for details.`
    );
  }
};

const A11Y_OPTIONS = {
  runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa'] },
};

// ─── Pages accessible without login ──────────────────────────────────────────

describe('WCAG 2.1 AA — Public pages (unauthenticated)', () => {

  it('Login page has no critical/serious WCAG violations', () => {
    LoginPage.visit();
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('Reset Password page has no critical/serious WCAG violations', () => {
    LoginPage.visit();
    LoginPage.clickForgotPassword();
    cy.url().should('include', '/auth/requestPasswordResetCode');
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });
});

// ─── Pages requiring authentication ──────────────────────────────────────────

describe('WCAG 2.1 AA — Authenticated pages', () => {

  beforeEach(() => {
    cy.loginWithEnvCredentials();
  });

  it('Dashboard has no critical/serious WCAG violations', () => {
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('Admin — System Users page has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToAdmin();
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('Admin — Add User form has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToAdmin();
    cy.contains('button', 'Add').click();
    cy.url().should('include', '/saveSystemUser');
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('PIM — Employee List page has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToPIM();
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('PIM — Add Employee form has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToPIM();
    cy.contains('button', 'Add').click();
    cy.url().should('include', '/addEmployee');
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('Leave — Leave List page has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToLeave();
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('Leave — Apply Leave form has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToLeave();
    NavigationComponent.navigateToApplyLeave();
    cy.url().should('include', '/applyLeave');
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });

  it('Admin — Job Titles page has no critical/serious WCAG violations', () => {
    NavigationComponent.navigateToAdmin();
    NavigationComponent.navigateToJobTitles();
    cy.injectAxe();
    cy.checkA11y(undefined, A11Y_OPTIONS, handleA11yViolations);
  });
});

